from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    counts=Counter(v for row in g for v in row if v!=0)
    color=min(counts, key=counts.get)
    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==color]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    mask={(r-r0,c-c0) for r,c in pts}
    h,w=len(g),len(g[0]); mh,mw=r1-r0+1,c1-c0+1
    for a in range(h-mh+1):
        for b in range(w-mw+1):
            if all(g[a+dr][b+dc]==0 for dr,dc in mask):
                for dr,dc in mask:
                    g[a+dr][b+dc]=color
    return g

